//! 🦴️ Solver-neutral analytical geometry projected from current parent values; no solver or retained state.
use crate::{ModelSnapshot, Point3, StructuralLocation, StructuralLoad, StructuralSupport, TopConstraint};
use super::super::storey_levels::{StoreyLevel, vertical_of, target_of};
use super::super::wall_layout::WallLayout;
use super::super::element_solids::{SolidEntry, placement_of, dep_object, dep_value};
use crate::standards::v1::subsets::any::schema::authored::plan::segment_of;
use semio_framework_value::DslValue;
use std::collections::BTreeMap;
/// 📐️ Unsolved structural member in world SI coordinates; path stations are normalized by exact analytical length.
#[derive(semio_framework_value::RetireOwned, Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue, semio_framework_value::RetainedClone)]
pub struct AnalyticalMember { pub element: String, pub storey: String, pub kind: String, pub path: Vec<Point3>, pub boundary: Vec<Point3>, pub holes: Vec<Vec<Point3>>, pub length: f64, pub area: f64, pub start_offset: f64, pub end_offset: f64 }
/// 🔗️ A rigid eccentricity between connected physical members; no stiffness is invented.
#[derive(semio_framework_value::RetireOwned, Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue, semio_framework_value::RetainedClone)]
pub struct RigidLink { pub member: String, pub other: String, pub start: Point3, pub end: Point3, pub length: f64 }
/// 🧱️ Authored support resolved on current world geometry.
#[derive(semio_framework_value::RetireOwned, Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue, semio_framework_value::RetainedClone)]
pub struct ResolvedSupport { pub authored: StructuralSupport, pub points: Vec<Point3> }
/// ⬇️ Authored load with current application geometry and load-case factor.
#[derive(semio_framework_value::RetireOwned, Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue, semio_framework_value::RetainedClone)]
pub struct ResolvedLoad { pub authored: StructuralLoad, pub points: Vec<Point3>, pub factor: f64 }
/// 📦️ Structural solver input projection; findings report orphaned or unsupported authored records.
#[derive(semio_framework_value::RetireOwned, Clone, Debug, Default, PartialEq, value_derive::ToValue, value_derive::FromValue, semio_framework_value::RetainedClone)]
pub struct StructuralAnalysis { pub members: BTreeMap<String, AnalyticalMember>, pub rigid_links: BTreeMap<String, RigidLink>, pub supports: BTreeMap<String, ResolvedSupport>, pub loads: BTreeMap<String, ResolvedLoad>, pub findings: Vec<String> }
pub const READS: &[&str] = &["walls", "beams", "columns", "slabs", "wall_types", "beam_types", "column_types", "slab_types", "storeys", "buildings", "sites", "supports", "load_cases", "loads"];
/// 🔑️ Every authored input not supplied by a graph parent.
pub fn dependency(model: &ModelSnapshot) -> DslValue { dep_object([("walls", dep_value(&model.walls)), ("beams", dep_value(&model.beams)), ("columns", dep_value(&model.columns)), ("slabs", dep_value(&model.slabs)), ("wall_types", dep_value(&model.wall_types)), ("beam_types", dep_value(&model.beam_types)), ("column_types", dep_value(&model.column_types)), ("slab_types", dep_value(&model.slab_types)), ("storeys", dep_value(&model.storeys)), ("buildings", dep_value(&model.buildings)), ("sites", dep_value(&model.sites)), ("supports", dep_value(&model.supports)), ("load_cases", dep_value(&model.load_cases)), ("loads", dep_value(&model.loads))]) }
fn distance(a: Point3, b: Point3) -> f64 { ((a.x-b.x).powi(2)+(a.y-b.y).powi(2)+(a.z-b.z).powi(2)).sqrt() }
fn world(model: &ModelSnapshot, levels: &BTreeMap<String, StoreyLevel>, storey: &str, p: Point3) -> Point3 { let placement=placement_of(model, storey, levels.get(storey)); let (sin,cos)=placement.rotation.sin_cos(); Point3 { x: placement.x+cos*p.x-sin*p.y, y:placement.y+sin*p.x+cos*p.y, z:p.z+placement.z } }
fn at(member: &AnalyticalMember, station: f64) -> Point3 { let total: f64 = member.path.windows(2).map(|pair| distance(pair[0],pair[1])).sum(); let mut left=station*total; for pair in member.path.windows(2) { let segment=distance(pair[0],pair[1]); if left<=segment && segment>0.0 { let t=left/segment; return Point3{x:pair[0].x+(pair[1].x-pair[0].x)*t,y:pair[0].y+(pair[1].y-pair[0].y)*t,z:pair[0].z+(pair[1].z-pair[0].z)*t}; } left-=segment; } member.path.last().copied().unwrap_or(Point3{x:0.0,y:0.0,z:0.0}) }
/// 📍️ Current application geometry for a normalized location.
pub fn location_points(member: &AnalyticalMember, location: &StructuralLocation) -> Vec<Point3> { match location { StructuralLocation::Point{station}=>vec![at(member,*station)],StructuralLocation::Line{start,end}=>vec![at(member,*start),at(member,*end)],StructuralLocation::Area=>member.boundary.clone() } }
/// 🧮️ Projects existing storey, wall-layout and solid graph values into one structural analysis result.
pub fn analysis_of(model: &ModelSnapshot, levels: &BTreeMap<String, StoreyLevel>, layouts: &BTreeMap<&str,&WallLayout>, solids: &BTreeMap<&str,&SolidEntry>) -> StructuralAnalysis {
 let mut out=StructuralAnalysis::default();
 let mut add=|id:&String,storey:&String,kind:&str,path:Vec<Point3>,boundary:Vec<Point3>,holes:Vec<Vec<Point3>>,length:f64,area:f64,start_offset:f64,end_offset:f64| { if length>1e-9 || area>1e-9 { out.members.insert(id.clone(), AnalyticalMember {element:id.clone(),storey:storey.clone(),kind:kind.into(),path:path.into_iter().map(|p|world(model,levels,storey,p)).collect(),boundary:boundary.into_iter().map(|p|world(model,levels,storey,p)).collect(),holes:holes.into_iter().map(|ring|ring.into_iter().map(|p|world(model,levels,storey,p)).collect()).collect(),length,area,start_offset,end_offset}); } };
 for (id,column) in &model.columns { if !solids.contains_key(id.as_str()) { continue; } let Some(level)=levels.get(&column.storey) else {continue}; let (base,top)=vertical_of(column.base_offset,&column.top,level,target_of(&column.top,levels)); let tilt=column.tilt.as_ref(); let shift=tilt.map_or(0.0,|t|(top-base)*t.angle.tan()); let direction=tilt.map_or(0.0,|t|t.direction); let a=Point3{x:column.position.x,y:column.position.y,z:base}; let b=Point3{x:a.x+shift*direction.cos(),y:a.y+shift*direction.sin(),z:top}; add(id,&column.storey,"column",vec![a,b],Vec::new(),Vec::new(),distance(a,b),0.0,0.0,0.0); }
 for (id,beam) in &model.beams { let Some(solid)=solids.get(id.as_str()) else {continue}; let Some(level)=levels.get(&beam.storey) else {continue}; let segment=segment_of(&beam.axis); let top=level.top_elevation+beam.top_offset; let end=level.top_elevation+beam.end_top_offset.unwrap_or(beam.top_offset); let depth=solid.solid.bounds.max.z-solid.solid.bounds.min.z; let mut path=Vec::new(); let steps=if matches!(beam.axis,crate::Axis::Arc{..}) {64} else {1}; for i in 0..=steps {let t=i as f64/steps as f64; let p=segment.point_at_length(t*segment.length()); path.push(Point3{x:p.x,y:p.y,z:top+(end-top)*t-depth/2.0});} let length=segment.length().hypot(end-top); add(id,&beam.storey,"beam",path,Vec::new(),Vec::new(),length,0.0,0.0,0.0); }
 for (id,wall) in &model.walls { let Some(layout)=layouts.get(id.as_str()) else {continue}; let segment=segment_of(&wall.axis); let steps=if matches!(wall.axis,crate::Axis::Arc{..}) {64} else {1}; let mut path=Vec::new(); let mut boundary=Vec::new(); let offset=(layout.offset_left+layout.offset_right)/2.0; let axis=segment.offset(offset).unwrap_or(segment); for i in 0..=steps {let t=i as f64/steps as f64;let p=axis.point_at_length(axis.length()*t);path.push(Point3{x:p.x,y:p.y,z:(layout.base_z+layout.top_z)/2.0});boundary.push(Point3{x:p.x,y:p.y,z:layout.base_z});} for p in path.iter().rev() {boundary.push(Point3{x:p.x,y:p.y,z:layout.top_z});} add(id,&wall.storey,"wall",path,boundary,Vec::new(),axis.length(),axis.length()*layout.height,0.0,0.0); }
 for (id,slab) in &model.slabs { let Some(solid)=solids.get(id.as_str()) else {continue}; let Some(level)=levels.get(&slab.storey) else {continue}; let slope=slab.slope.as_ref(); let thickness=model.slab_types.get(&slab.slab_type).map_or(0.0,|kind|kind.layers.iter().map(|layer|layer.thickness).sum::<f64>()); let outline=super::super::element_solids::plan_kit::bulged(&slab.boundary); let top=super::super::element_solids::slabs::top_plane(slab,&outline,level.elevation+slab.offset); let p=|v:&crate::Vertex|Point3{x:v.point.x,y:v.point.y,z:top.at(semio_framework_geometry::Point::new(v.point.x,v.point.y))-thickness/2.0}; let boundary:Vec<_>=slab.boundary.iter().map(p).collect(); let ring=|vs:&Vec<crate::Vertex>|vs.iter().map(|v|semio_framework_geometry::loops::Vertex::new(semio_framework_geometry::Point::new(v.point.x,v.point.y),v.bulge)).collect::<Vec<_>>(); let area=(semio_framework_geometry::loops::signed_area(&ring(&slab.boundary)).abs()-slab.holes.iter().map(|h|semio_framework_geometry::loops::signed_area(&ring(h)).abs()).sum::<f64>())/slope.map_or(1.0,|s|s.angle.cos()); add(id,&slab.storey,"slab",boundary.iter().take(2).copied().collect(),boundary,slab.holes.iter().map(|h|h.iter().map(p).collect()).collect(),0.0,area,0.0,0.0); }
 for (id,support) in &model.supports { if let Some(problem)=crate::support_problem(model,support) { out.findings.push(format!("support/{id}: {problem}"));continue; } if let Some(member)=out.members.get(&support.member) {let points=location_points(member,&support.location).into_iter().map(|p|Point3{x:p.x+support.offset.x,y:p.y+support.offset.y,z:p.z+support.offset.z}).collect();out.supports.insert(id.clone(),ResolvedSupport{authored:support.clone(),points});}else{out.findings.push(format!("support/{id}: member has no analytical geometry"));} }
 for (id,load) in &model.loads { if let Some(problem)=crate::load_problem(model,load) {out.findings.push(format!("load/{id}: {problem}"));continue;} if let Some(member)=out.members.get(&load.member) {out.loads.insert(id.clone(),ResolvedLoad{authored:load.clone(),points:location_points(member,&load.location),factor:model.load_cases[&load.load_case].factor});}else{out.findings.push(format!("load/{id}: member has no analytical geometry"));} }
 for (id,beam) in out.members.iter().filter(|(_,m)|m.kind=="beam") { for (other,column) in out.members.iter().filter(|(_,m)|m.kind=="column" && m.storey==beam.storey) { let Some(authored)=model.columns.get(other) else {continue};let reach=super::super::element_solids::columns::reach(model,authored).unwrap_or(0.0);for (end,p) in [beam.path.first(),beam.path.last()].into_iter().enumerate() {let Some(p)=p else{continue};let a=column.path[0];let b=*column.path.last().unwrap();let dz=b.z-a.z;if dz.abs()<1e-9||p.z<a.z-1e-6||p.z>b.z+1e-6 {continue;}let t=(p.z-a.z)/dz;let q=Point3{x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t,z:p.z};let length=distance(*p,q);if length<=reach+1e-6 {out.rigid_links.insert(format!("{id}/{end}/{other}"),RigidLink{member:id.clone(),other:other.clone(),start:*p,end:q,length});}} } }
 out
}
